// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.oom;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class OomDebugDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya",  new BigDecimal("250000"));

        Diagnostics diag = new Diagnostics();
        diag.logHeap("before reconciliation");

        ReconciliationJob job = new ReconciliationJob();
        // FIXED streaming mode: processes and discards each record → flat memory.
        long matched = job.runStreaming(rajesh, priya, 500_000);

        diag.logHeap("after reconciliation");
        final long m = matched;
        log.info(() -> "Reconciliation matched " + m + " records (streaming, no OOM)");

        // The leaky mode (job.runLeaky) would accumulate all records and OOM.
        log.warning(() -> "To reproduce the OOM, run runLeaky() with -Xmx32m "
                + "and -XX:+HeapDumpOnOutOfMemoryError, then analyze the dump.");
    }
}

// ─── Would be in Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private final BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    String getAccountId() { return accountId; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in ReconciliationJob.java ───
class ReconciliationJob {
    // LEAKY: accumulates every record forever → heap OOM on large input.
    private final java.util.List<String> allRecords = new java.util.ArrayList<>();
    long runLeaky(Account a, Account b, int n) {
        long matched = 0;
        for (int i = 0; i < n; i++) {
            allRecords.add("REC-" + i + "-" + a.getAccountId() + "-" + b.getAccountId());
            matched++;
        }
        return matched; // allRecords keeps growing → eventual OutOfMemoryError
    }

    // FIXED: streaming — process then discard each record → memory stays flat.
    long runStreaming(Account a, Account b, int n) {
        long matched = 0;
        for (int i = 0; i < n; i++) {
            String record = "REC-" + i + "-" + a.getAccountId() + "-" + b.getAccountId();
            if (record.length() > 0) matched++; // process immediately
            // 'record' becomes garbage at loop end → reclaimed cheaply
        }
        return matched;
    }
}

// ─── Would be in Diagnostics.java ───
class Diagnostics {
    private static final Logger log = Logger.getLogger("BankLog");
    void logHeap(String phase) {
        Runtime rt = Runtime.getRuntime();
        long usedMb = (rt.totalMemory() - rt.freeMemory()) / (1024 * 1024);
        long maxMb = rt.maxMemory() / (1024 * 1024);
        log.info(() -> "Heap " + phase + ": used=" + usedMb + "MB / max=" + maxMb + "MB");
    }
}
